(async () => {
    // ============================================================
    // 0. Framework laden (Lädt das ECHTE Framework!)
    // ============================================================
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }
    await new Promise(resolve => setTimeout(resolve, 150)); 

    if (typeof DSK === "undefined") {
        ui.notifications.error("Das DSK-Framework konnte nicht geladen werden!");
        return;
    }

    const gabenName = "Geisterfreund";
    const ahne = "Zerzal";
    const finalEffektName = `${gabenName} (${ahne})`;
    const sfName = finalEffektName;

    const stufenTexte = {
        1: "Unstillbarer Hass",
        2: "Feindselig",
        3: "Abscheu / Ablehnung",
        4: "Abneigung",
        5: "Neutral",
        6: "Zuneigung",
        7: "Vertrauen / Freundschaft"
    };

    const stufenErklaerung = Object.entries(stufenTexte).map(([k, v]) => `${k}: ${v}`).join("<br>");
    const beschreibungFuerEnde = "Die geweckten Sympathien verfliegen. Der Geist besinnt sich auf seine wahre Haltung.";

    // Hilfsfunktion: Finde alle Spieler-IDs, denen ein Akteur gehört
    const getOwners = (act) => {
        if (!act) return [];
        const ownership = act.ownership || act.permission || {};
        return Object.entries(ownership)
            .filter(([id, lvl]) => lvl === 3 && id !== "default")
            .map(([id]) => id);
    };

    // ============================================================
    // HOOK 0: WIRKUNGSENDE
    // ============================================================
    if (DSK.EffektEnde) {
        DSK.EffektEnde.Register(
            "geisterfreundZerzal", 
            finalEffektName, 
            beschreibungFuerEnde
        );
    }

    // ============================================================
    // HOOK 1: SONDERFERTIGKEIT LÖSCHEN BEIM EFFEKTENDE
    // ============================================================
    if (window.onGeisterfreundDelete) Hooks.off("preDeleteActiveEffect", window.onGeisterfreundDelete);

    window.onGeisterfreundDelete = async (effect) => {
        if (effect.name !== finalEffektName || !effect.parent) return;

        const geistActor = effect.parent;
        const sfItem = geistActor.items.find(i => i.name === sfName && i.type === "specialability");

        if (sfItem) await sfItem.delete();
    };
    Hooks.on("preDeleteActiveEffect", window.onGeisterfreundDelete);

    // ============================================================
    // HOOK 2: ÜBERWACHUNG CHARAKTERBOGEN (SONDERFERTIGKEIT)
    // ============================================================
    if (window.onGeisterfreundUpdate) Hooks.off("updateItem", window.onGeisterfreundUpdate);

    window.onGeisterfreundUpdate = async (item, changes) => {
        if (item.type !== "specialability" || item.name !== sfName) return;
        if (!changes.system || changes.system.level === undefined) return;

        const geistActor = item.parent || item.actor; // V11/V12
        if (!geistActor) return;

        const neueStufe = changes.system.level;
        const erklaerungText = stufenTexte[neueStufe] || "Unbekannt";

        const casterUuid = item.flags?.dsk?.casterUuid;
        const casterActor = casterUuid ? await fromUuid(casterUuid) : null;

        const ownerIds = Array.from(new Set([
            ...game.users.filter(u => u.isGM).map(u => u.id),
            ...getOwners(geistActor),
            ...getOwners(casterActor)
        ])).filter(id => game.users.get(id));

        ChatMessage.create({
            whisper: ownerIds,
            content: `
                ${DSK.UI.Header(finalEffektName, DSK.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="text-align:center; font-weight:bold; font-size:1.15em; margin-bottom:8px;">
                        Beziehungsänderung
                    </p>
                    <p style="font-size:0.95em; line-height:1.35;">
                        Durch Ereignisse hat sich die Beziehungsstufe bei <b>${geistActor.name}</b> verändert.<br><br>
                        <b>Neue Stufe:</b> ${neueStufe}<br>
                        <i>Das bedeutet: Das Ziel empfindet <b>${erklaerungText}</b>.</i>
                    </p>
                </div>
            `
        });

        const aktEffekt = geistActor.effects.find(e => (e.name || e.label) === finalEffektName);
        if (aktEffekt && aktEffekt.flags?.dsk?.value !== neueStufe) {
            Hooks.off("updateActiveEffect", window.onGeisterfreundEffektUpdate);
            await aktEffekt.update({ "flags.dsk.value": neueStufe });
            Hooks.on("updateActiveEffect", window.onGeisterfreundEffektUpdate);
        }
    };
    Hooks.on("updateItem", window.onGeisterfreundUpdate);


    // ============================================================
    // HOOK 3: ÜBERWACHUNG EFFEKTE-ÜBERSICHT (DEIN TOOL)
    // ============================================================
    if (window.onGeisterfreundEffektUpdate) Hooks.off("updateActiveEffect", window.onGeisterfreundEffektUpdate);

    window.onGeisterfreundEffektUpdate = async (effect, changes) => {
        if ((effect.name || effect.label) !== finalEffektName) return;

        const neueStufe = changes.flags?.dsk?.value;
        if (neueStufe === undefined) return;

        const geistActor = effect.parent;
        if (!geistActor) return;

        const erklaerungText = stufenTexte[neueStufe] || "Unbekannt";

        const casterUuid = effect.flags?.dsk?.casterUuid || effect.origin;
        let casterActor = null;
        if (casterUuid) {
            try {
                const casterDoc = await fromUuid(casterUuid);
                casterActor = casterDoc?.documentName === "Token" ? casterDoc.actor : casterDoc;
            } catch(e) {}
        }

        const ownerIds = Array.from(new Set([
            ...game.users.filter(u => u.isGM).map(u => u.id),
            ...getOwners(geistActor),
            ...getOwners(casterActor)
        ])).filter(id => game.users.get(id));

        ChatMessage.create({
            whisper: ownerIds,
            content: `
                ${DSK.UI.Header(finalEffektName, DSK.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="text-align:center; font-weight:bold; font-size:1.15em; margin-bottom:8px;">
                        Beziehungsänderung
                    </p>
                    <p style="font-size:0.95em; line-height:1.35;">
                        Durch Ereignisse hat sich die Beziehungsstufe bei <b>${geistActor.name}</b> verändert.<br><br>
                        <b>Neue Stufe:</b> ${neueStufe}<br>
                        <i>Das bedeutet: Das Ziel empfindet <b>${erklaerungText}</b>.</i>
                    </p>
                </div>
            `
        });

        const sfItem = geistActor.items.find(i => i.name === sfName && i.type === "specialability");
        if (sfItem && sfItem.system.level !== neueStufe) {
            Hooks.off("updateItem", window.onGeisterfreundUpdate); 
            await sfItem.update({ "system.level": neueStufe });
            Hooks.on("updateItem", window.onGeisterfreundUpdate); 
        }
    };
    Hooks.on("updateActiveEffect", window.onGeisterfreundEffektUpdate);

    // ============================================================
    // 1. WIRKENDEN (CASTER) & QS AUS FLAG ERMITTELN 
    // ============================================================
    const casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    }

    let qsWert = casterActor.getFlag("world", "letzteGabenQS") || 1;
    if (casterActor.getFlag("world", "letzteGabenQS")) {
        await casterActor.unsetFlag("world", "letzteGabenQS"); 
    }

    if (typeof testData !== "undefined") {
        qsWert = Number(testData?.result?.QL || testData?.qualityStep || qsWert);
    }

    if (qsWert <= 0) {
        return ui.notifications.warn("Die Probe ist fehlgeschlagen.");
    }

    const casterName = DSK.ResolveTokenName(casterActor);
    const dauerMinuten = qsWert * 5;
    const dauerText = `${dauerMinuten} Minuten<br><span style="font-size: 0.85em; font-weight: normal;">(QS x 5)</span>`;

    // ============================================================
    // 2. Ziel-Token ermitteln (Geist über Target markiert)
    // ============================================================
    let targetToken = game.user.targets.first();
    if (!targetToken) {
        return ui.notifications.warn("Bitte markiere (Target) zuerst das Token des Geistes auf der Karte!");
    }
    let targetActor = targetToken.actor;
    if (!targetActor) {
        return ui.notifications.warn("Das gewählte Ziel hat keinen gültigen Charakterbogen!");
    }

    let sfItem = targetActor.items.find(i => i.name === sfName && i.type === "specialability");
    let startVal = sfItem ? sfItem.system.level : (Math.random() < 0.5 ? 4 : 5);

    // ============================================================
    // 3. Dialog & Anwendung
    // ============================================================
    new Dialog({
        title: finalEffektName,
        content: `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK.UI.Header(finalEffektName, DSK.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="font-size:0.9em; margin:0;">Bitte gib die aktuelle Beziehungsstufe für <b>${targetActor.name}</b> ein.</p>
                    <form style="margin-top:10px;">
                        <div class="form-group" style="margin-bottom:8px; display:flex; justify-content:space-between; align-items:center;">
                            <label><b>Start-Stufe (1-7):</b></label>
                            <input type="number" id="startLevel" value="${startVal}" min="1" max="7" style="width: 60px; text-align: center;">
                        </div>
                    </form>
                </div>
            </div>`,
        buttons: {
            ok: {
                label: "Gabe wirken",
                callback: async (html) => {
                    let sStufe = Number(html.find("#startLevel").val());
                    let neueStufe = Math.min(7, sStufe + qsWert);

                    const basisBeschreibung = `<b>${casterName}</b> beeinflusst die Gefühle von <b>${targetActor.name}</b>.<br><br>` +
                        `• <b>Startstufe:</b> ${sStufe}<br>` +
                        `• <b>Verbesserung:</b> +${qsWert} (QS)<br>` +
                        `• <b>Neue Stufe:</b> ${neueStufe} (${stufenTexte[neueStufe]})<br><br>` +
                        `<b>Beziehungsstufen:</b><br>${stufenErklaerung}`;

                    // SF anlegen/aktualisieren - HIER SPEICHERN WIR DIE UUID DES CASTERS!
                    let oldSF = targetActor.items.find(i => i.name === sfName && i.type === "specialability");
                    if (oldSF) {
                        Hooks.off("updateItem", window.onGeisterfreundUpdate);
                        await oldSF.update({
                            system: { level: neueStufe, rule: stufenErklaerung, description: { value: basisBeschreibung } },
                            flags: { dsk: { casterUuid: casterActor.uuid } }
                        });
                        Hooks.on("updateItem", window.onGeisterfreundUpdate);
                    } else {
                        Hooks.off("updateItem", window.onGeisterfreundUpdate);
                        await targetActor.createEmbeddedDocuments("Item", [{
                            name: sfName, 
                            type: "specialability", 
                            img: DSK.Symbol(ahne),
                            flags: { dsk: { casterUuid: casterActor.uuid } },
                            system: { level: neueStufe, max: 7, rule: stufenErklaerung, description: { value: basisBeschreibung } }
                        }]);
                        Hooks.on("updateItem", window.onGeisterfreundUpdate);
                    }

                    // Alten Effekt aufräumen
                    let oldEff = targetActor.effects.find(e => (e.name || e.label) === finalEffektName);
                    if (oldEff) {
                        Hooks.off("preDeleteActiveEffect", window.onGeisterfreundDelete);
                        await oldEff.delete();
                        Hooks.on("preDeleteActiveEffect", window.onGeisterfreundDelete);
                    }

                    const kompletterEffektText = `
                        <b>Gabenwirkung:</b><br>${basisBeschreibung}<br><hr>
                        <b>Erfolg:</b><br>• ${targetActor.name}<br><hr>
                        <b>Wirkungsdauer:</b><br>${dauerText.replace(/<br>/g, ' ')}
                    `.trim();

                    // ============================================================
                    // EFFEKT STRIKT ÜBER DAS FRAMEWORK 
                    // ============================================================
                    Hooks.off("updateActiveEffect", window.onGeisterfreundEffektUpdate);
                    await DSK.Effekt.Anwenden({
                        name: finalEffektName,
                        ahne: ahne,
                        beschreibung: kompletterEffektText,
                        gabeZiel: "geist",
                        qs: qsWert,
                        formel: "0",
                        skills: [],
                        ziel: targetActor,
                        flags: { 
                            dsk: { 
                                value: neueStufe, 
                                max: 7, 
                                casterUuid: casterActor.uuid 
                            } 
                        }
                    });
                    Hooks.on("updateActiveEffect", window.onGeisterfreundEffektUpdate);

                    // ============================================================
                    // MANUELLE CHATKARTE
                    // ============================================================
                    let erfolgHtml = `
                        <p><span style="color:#18940F; font-weight:bold;">Erfolg</span></p>
                        <ul class="dsklist" style="font-weight:normal; margin-top:4px;">
                            <li>${targetActor.name}</li>
                        </ul>
                    `;

                    ChatMessage.create({
                        speaker: ChatMessage.getSpeaker({ actor: casterActor }),
                        content: `
                            ${DSK.UI.Header(finalEffektName, DSK.Symbol(ahne))}
                            <div class="dskbox2" style="margin-top:10px;">
                                <p><b>Gabenwirkung:</b></p>
                                <p>${basisBeschreibung}</p>
                                <hr>
                                ${erfolgHtml}
                                <hr>
                                <p style="text-align:center; font-weight:bold;">
                                    Wirkungsdauer:<br>${dauerText}
                                </p>
                            </div>
                        `
                    });
                }
            }
        },
        default: "ok",
        render: (html) => {
            const container = html instanceof jQuery ? html[0] : html;
            if (container) {
                const buttons = container.querySelectorAll('.dialog-button');
                buttons.forEach(btn => {
                    btn.style.background = 'linear-gradient(#76301b,#582617)';
                    btn.style.color = '#f8f6f5';
                    btn.style.border = '1px solid #000';
                    btn.style.fontWeight = 'bold';
                });
            }
        }
    }).render(true);

})();
